import type { BuildOptions, Page } from './types';
import type { SsgConfig } from './config';

export interface SsgContext {
  options: BuildOptions;
  config: SsgConfig;
  engine: import('./engine').SsgEngine;
  pages: Page[];
  templateDir: string;
  startTime: number;
}

export interface Plugin {
  name: string;
  onStart?(ctx: SsgContext): void | Promise<void>;
  beforeBuild?(ctx: SsgContext): void | Promise<void>;
  afterBuild?(ctx: SsgContext): void | Promise<void>;
  onFile?(page: Page, ctx: SsgContext): Page | void | Promise<Page | void>;
  onEnd?(ctx: SsgContext): void | Promise<void>;
}

export type PluginHook =
  | 'onStart'
  | 'beforeBuild'
  | 'afterBuild'
  | 'onFile'
  | 'onEnd';

import fs from 'fs/promises';
import path from 'path';
import { parseFrontmatter, renderMarkdown } from './markdown';
import { Page } from './types';

const MARKDOWN_EXTENSIONS = new Set(['.md', '.markdown']);

export function isMarkdownFile(fileName: string): boolean {
  return MARKDOWN_EXTENSIONS.has(path.extname(fileName).toLowerCase());
}

export function slugFromSource(source: string): string {
  const withoutExt = source.replace(/\.md$/i, '').replace(/\.markdown$/i, '');
  const slug = withoutExt
    .split(/[\\/]+/)
    .map((segment) =>
      segment.replace(/[\s_]+/g, '-').replace(/[^a-zA-Z0-9-]/g, '')
    )
    .join('/');
  return slug.replace(/^-+|-+$/g, '').replace(/\/+/g, '/');
}

export function titleFromSource(source: string): string {
  const slug = slugFromSource(source);
  const name = slug.split('/').pop() ?? slug;
  return name
    .split('-')
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

export async function collectMarkdownFiles(contentDir: string): Promise<string[]> {
  const files: string[] = [];

  async function walk(dir: string, relative: string): Promise<void> {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    entries.sort((a, b) => a.name.localeCompare(b.name));
    for (const entry of entries) {
      const relPath = path.join(relative, entry.name);
      const absPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(absPath, relPath);
      } else if (entry.isFile() && isMarkdownFile(entry.name)) {
        files.push(relPath);
      }
    }
  }

  await walk(contentDir, '');
  return files;
}

export async function buildPage(contentDir: string, source: string): Promise<Page> {
  const absPath = path.join(contentDir, source);
  const raw = await fs.readFile(absPath, 'utf-8');
  const { title, date, tags, template, layout, body } = parseFrontmatter(raw);
  const html = await renderMarkdown(body);

  return {
    slug: slugFromSource(source),
    source,
    title: title ?? titleFromSource(source),
    date,
    tags,
    template,
    layout,
    body,
    html,
  };
}

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function renderPageHtml(page: Page): string {
  const title = escapeHtml(page.title);
  const date = page.date
    ? `<p class="page-date">${escapeHtml(page.date)}</p>`
    : '';
  const tags = page.tags.length
    ? `<ul class="page-tags">${page.tags
        .map((tag) => `<li class="tag">${escapeHtml(tag)}</li>`)
        .join('')}</ul>`
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title}</title>
</head>
<body>
  <nav><a href="index.html">&larr; Home</a></nav>
  <article>
    <h1>${title}</h1>
    ${date}
    ${tags}
    <div class="content">
${page.html}
    </div>
  </article>
</body>
</html>
`;
}

function comparePages(a: Page, b: Page): number {
  if (a.date && b.date) {
    const cmp = new Date(b.date).getTime() - new Date(a.date).getTime();
    if (cmp !== 0) return cmp;
  }
  if (a.date && !b.date) return -1;
  if (!a.date && b.date) return 1;
  return a.title.localeCompare(b.title);
}

export function renderIndexHtml(pages: Page[]): string {
  const items = pages
    .slice()
    .sort(comparePages)
    .map((page) => {
      const href = `${page.slug}.html`;
      const date = page.date
        ? `<span class="index-date">${escapeHtml(page.date)}</span>`
        : '';
      const tags = page.tags.length
        ? ` <span class="index-tags">[${page.tags
            .map((tag) => escapeHtml(tag))
            .join(', ')}]</span>`
        : '';
      return `    <li><a href="${escapeHtml(href)}">${escapeHtml(page.title)}</a>${date}${tags}</li>`;
    })
    .join('\n');

  const total = pages.length;
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Index</title>
</head>
<body>
  <h1>Pages</h1>
  ${items.length ? `<ul>\n${items}\n</ul>` : '<p>No pages yet.</p>'}
  <p class="footer">${total} page${total === 1 ? '' : 's'}</p>
</body>
</html>
`;
}

import fs from 'fs/promises';
import path from 'path';
import { Plugin, PluginHook } from './plugin';

export interface SsgConfig {
  plugins?: PluginEntry[];
}

export type PluginEntry = Plugin | string | (() => Plugin | Promise<Plugin>);

const DEFAULT_PLUGINS_DIR = 'plugins';
const HOOKS: PluginHook[] = ['onStart', 'beforeBuild', 'afterBuild', 'onFile', 'onEnd'];

async function exists(filePath: string): Promise<boolean> {
  try {
    await fs.stat(filePath);
    return true;
  } catch {
    return false;
  }
}

function installTsSupport(): void {
  const extensions = (require as unknown as { extensions: Record<string, unknown> }).extensions;
  if (extensions['.ts']) return;

  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const ts = require('typescript');
  extensions['.ts'] = function (module: { _compile: (code: string, file: string) => void }, filename: string): void {
    const source = fs.readFileSync(filename, 'utf-8');
    const result = ts.transpileModule(source, {
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2020,
        esModuleInterop: true,
        moduleResolution: ts.ModuleResolutionKind.NodeJs,
      },
      fileName: filename,
    });
    module._compile(result.outputText, filename);
  };

  const Module = require('module') as {
    _resolveFilename: (
      request: string,
      parent: { filename?: string } | undefined,
      isMain: boolean,
      options?: unknown
    ) => string;
  };
  const originalResolve = Module._resolveFilename;
  Module._resolveFilename = function (
    request: string,
    parent: { filename?: string } | undefined,
    isMain: boolean,
    options?: unknown
  ): string {
    try {
      return originalResolve.call(this, request, parent, isMain, options);
    } catch (err) {
      if (parent && parent.filename && parent.filename.endsWith('.ts') && !path.extname(request)) {
        return originalResolve.call(this, `${request}.ts`, parent, isMain, options);
      }
      throw err;
    }
  };
}

function requireModule(filePath: string): unknown {
  if (filePath.endsWith('.ts')) {
    installTsSupport();
  }
  const mod = require(filePath) as { default?: unknown };
  return (mod && mod.default !== undefined ? mod.default : mod) as unknown;
}

function hasHook(candidate: unknown): boolean {
  const record = candidate as Record<string, unknown>;
  return HOOKS.some((hook) => typeof record?.[hook] === 'function');
}

function instantiate(candidate: unknown): unknown {
  if (candidate && typeof candidate === 'function') {
    try {
      return new (candidate as new () => unknown)();
    } catch {
      try {
        return (candidate as () => unknown)();
      } catch {
        return undefined;
      }
    }
  }
  return candidate;
}

function toPlugin(candidate: unknown): Plugin | undefined {
  const instance = instantiate(candidate);
  if (
    instance &&
    typeof instance === 'object' &&
    typeof (instance as Plugin).name === 'string' &&
    hasHook(instance)
  ) {
    return instance as Plugin;
  }
  return undefined;
}

function resolvePluginPath(entry: string, dir: string): string {
  if (path.isAbsolute(entry)) return entry;
  if (entry.startsWith('.')) return path.resolve(dir, entry);
  return path.resolve(dir, DEFAULT_PLUGINS_DIR, entry);
}

async function normalizeEntry(entry: PluginEntry, dir: string): Promise<Plugin | undefined> {
  if (typeof entry === 'string') {
    const mod = requireModule(resolvePluginPath(entry, dir));
    return toPlugin(mod);
  }
  if (typeof entry === 'function') {
    const candidate = await entry();
    return toPlugin(candidate);
  }
  return toPlugin(entry);
}

async function discoverPlugins(dir: string): Promise<Plugin[]> {
  const pluginsDir = path.join(dir, DEFAULT_PLUGINS_DIR);
  if (!(await exists(pluginsDir))) return [];

  let entries: fs.Dirent[];
  try {
    entries = await fs.readdir(pluginsDir, { withFileTypes: true });
  } catch {
    return [];
  }

  const discovered: Plugin[] = [];
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (!/\.(ts|js|mjs)$/.test(entry.name)) continue;
    let mod: unknown;
    try {
      mod = requireModule(path.join(pluginsDir, entry.name));
    } catch {
      continue;
    }
    const plugin = toPlugin(mod);
    if (plugin) discovered.push(plugin);
  }
  return discovered;
}

export async function loadConfig(dir: string = process.cwd()): Promise<SsgConfig> {
  const tsPath = path.join(dir, 'ssg.config.ts');
  const jsPath = path.join(dir, 'ssg.config.js');
  if (await exists(jsPath)) {
    const mod = requireModule(jsPath);
    return (mod as SsgConfig) ?? {};
  }
  if (await exists(tsPath)) {
    const mod = requireModule(tsPath);
    return (mod as SsgConfig) ?? {};
  }
  return {};
}

export async function loadConfiguredPlugins(
  dir: string = process.cwd()
): Promise<{ plugins: Plugin[]; config: SsgConfig }> {
  const config = await loadConfig(dir);
  const plugins: Plugin[] = [];
  const seen = new Set<string>();

  function add(plugin: Plugin | undefined): void {
    if (!plugin || seen.has(plugin.name)) return;
    seen.add(plugin.name);
    plugins.push(plugin);
  }

  for (const entry of config.plugins ?? []) {
    add(await normalizeEntry(entry, dir));
  }
  for (const plugin of await discoverPlugins(dir)) {
    add(plugin);
  }
  return { plugins, config };
}

import { Plugin, SsgContext } from '../plugin';
import { Page } from '../types';
import { buildPage } from '../core';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  async onFile(page: Page, ctx: SsgContext): Promise<Page> {
    return buildPage(ctx.options.contentDir, page.source);
  }
}

import { Plugin, SsgContext } from '../plugin';
import { Page } from '../types';
import { renderPageHtml } from '../core';
import {
  registerPartials,
  renderPageWithTemplates,
  templateDirExists,
} from '../template';

export class TemplatePlugin implements Plugin {
  name = 'template';

  async beforeBuild(ctx: SsgContext): Promise<void> {
    const templateDir = ctx.templateDir;
    if (await templateDirExists(templateDir)) {
      await registerPartials(templateDir);
    }
  }

  async onFile(page: Page, ctx: SsgContext): Promise<Page> {
    const templateDir = ctx.templateDir;
    const useTemplates = await templateDirExists(templateDir);
    page.renderedHtml = useTemplates
      ? await renderPageWithTemplates(page, templateDir)
      : renderPageHtml(page);
    return page;
  }
}

import http from 'http';
import fs from 'fs/promises';
import path from 'path';
import { AddressInfo } from 'net';
import chokidar from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import { Plugin, SsgContext } from '../plugin';
import { BuildOptions } from '../types';
import { defaultPlugins } from './index';
import { SsgEngine, createEngine } from '../engine';
import { loadConfiguredPlugins } from '../config';

type FileStats = Awaited<ReturnType<typeof fs.stat>>;

const DEFAULT_SERVE_HOST = 'localhost';
const DEFAULT_SERVE_PORT = 3000;
const LIVE_RELOAD_PATH = '/__ssg_ws';
const REBUILD_DEBOUNCE_MS = 100;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
};

export interface ServeOptions {
  contentDir: string;
  outputDir: string;
  templateDir?: string;
  port?: number;
  host?: string;
}

export interface DevServer {
  server: http.Server;
  port: number;
  host: string;
  watcher: chokidar.FSWatcher;
  wss: WebSocketServer;
  rebuild(): Promise<void>;
  close(): Promise<void>;
  onRebuild(callback: () => void): void;
}

export function liveReloadClientScript(): string {
  return `<script>
(function () {
  var scheme = location.protocol === 'https:' ? 'wss' : 'ws';
  var url = scheme + '://' + location.host + '${LIVE_RELOAD_PATH}';
  function connect() {
    var socket;
    try {
      socket = new WebSocket(url);
    } catch (err) {
      return;
    }
    socket.onmessage = function (event) {
      try {
        var message = JSON.parse(event.data);
        if (message && message.type === 'reload') {
          location.reload();
        }
      } catch (err) {}
    };
    socket.onclose = function () {
      setTimeout(connect, 1000);
    };
    socket.onerror = function () {
      socket.close();
    };
  }
  connect();
})();
</script>`;
}

export function injectLiveReloadScript(html: string): string {
  const script = liveReloadClientScript();
  const lower = html.toLowerCase();
  const bodyCloseIndex = lower.lastIndexOf('</body>');
  if (bodyCloseIndex !== -1) {
    return (
      html.slice(0, bodyCloseIndex) + `${script}\n` + html.slice(bodyCloseIndex)
    );
  }
  return html + script;
}

function contentTypeFor(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return MIME_TYPES[ext] ?? 'application/octet-stream';
}

function isPathInside(root: string, target: string): boolean {
  const relative = path.relative(root, target);
  return (
    relative === '' ||
    (!relative.startsWith('..') && !path.isAbsolute(relative))
  );
}

export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  private server: http.Server | undefined;
  private wss: WebSocketServer | undefined;
  private watcher: chokidar.FSWatcher | undefined;
  private ctx: SsgContext | undefined;
  private rebuildCallbacks: Array<() => void> = [];
  private rebuildTimer: NodeJS.Timeout | undefined;
  private port = 0;
  private host = DEFAULT_SERVE_HOST;

  constructor(private options: ServeOptions) {}

  async onStart(ctx: SsgContext): Promise<void> {
    this.ctx = ctx;
    const outputDir = path.resolve(ctx.options.outputDir);
    const host = this.options.host ?? DEFAULT_SERVE_HOST;
    const requestedPort = this.options.port ?? DEFAULT_SERVE_PORT;
    this.host = host;

    const wss = new WebSocketServer({ noServer: true });
    this.wss = wss;

    async function sendFile(
      res: http.ServerResponse,
      filePath: string,
      injectHtml: boolean
    ): Promise<void> {
      const data = await fs.readFile(filePath);
      if (injectHtml && path.extname(filePath).toLowerCase() === '.html') {
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(injectLiveReloadScript(data.toString('utf-8')));
        return;
      }
      res.writeHead(200, { 'Content-Type': contentTypeFor(filePath) });
      res.end(data);
    }

    async function handleRequest(
      req: http.IncomingMessage,
      res: http.ServerResponse
    ): Promise<void> {
      try {
        const url = new URL(req.url ?? '/', `http://${req.headers.host ?? host}`);
        const pathname = decodeURIComponent(url.pathname);
        let filePath = path.normalize(path.join(outputDir, pathname));
        if (!isPathInside(outputDir, filePath)) {
          res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
          res.end('Forbidden');
          return;
        }

        let stats: FileStats;
        try {
          stats = await fs.stat(filePath);
        } catch {
          res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
          res.end('Not Found');
          return;
        }

        if (stats.isDirectory()) {
          filePath = path.join(filePath, 'index.html');
          try {
            await fs.stat(filePath);
          } catch {
            res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
            res.end('Not Found');
            return;
          }
        }

        await sendFile(res, filePath, true);
      } catch {
        res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Internal Server Error');
      }
    }

    const server = http.createServer((req, res) => {
      handleRequest(req, res).catch(() => {
        res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Internal Server Error');
      });
    });
    this.server = server;

    server.on('upgrade', (req, socket, head) => {
      let pathname = '/';
      try {
        pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
      } catch {
        // ignore malformed upgrade requests
      }
      if (pathname === LIVE_RELOAD_PATH) {
        wss.handleUpgrade(req, socket, head, (ws) => {
          wss.emit('connection', ws, req);
        });
      } else {
        socket.destroy();
      }
    });

    const watchPaths = [path.resolve(ctx.options.contentDir), ctx.templateDir];
    const watcher = chokidar.watch(watchPaths, {
      ignoreInitial: true,
      ignorePermissionErrors: true,
    });
    this.watcher = watcher;
    watcher.on('all', (_event, filePath) => {
      if (path.resolve(filePath).startsWith(outputDir + path.sep)) {
        return;
      }
      this.scheduleRebuild();
    });

    await new Promise<void>((resolve, reject) => {
      server.once('error', reject);
      server.listen(requestedPort, host, () => resolve());
    });

    const address = server.address() as AddressInfo;
    this.port = address.port;
  }

  afterBuild(): void {
    this.broadcastReload();
    for (const callback of this.rebuildCallbacks) {
      callback();
    }
  }

  async onEnd(): Promise<void> {
    if (this.rebuildTimer) {
      clearTimeout(this.rebuildTimer);
      this.rebuildTimer = undefined;
    }
    if (this.watcher) {
      await this.watcher.close();
      this.watcher = undefined;
    }
    if (this.wss) {
      for (const client of this.wss.clients) {
        client.terminate();
      }
      await new Promise<void>((resolve) => this.wss?.close(() => resolve()));
      this.wss = undefined;
    }
    if (this.server) {
      await new Promise<void>((resolve) => this.server?.close(() => resolve()));
      this.server = undefined;
    }
  }

  broadcastReload(): void {
    const data = JSON.stringify({ type: 'reload' });
    for (const client of this.wss?.clients ?? []) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(data);
      }
    }
  }

  rebuild(): Promise<void> {
    return this.ctx?.engine.build() ?? Promise.resolve();
  }

  scheduleRebuild(): void {
    if (this.rebuildTimer) {
      clearTimeout(this.rebuildTimer);
    }
    this.rebuildTimer = setTimeout(() => {
      this.rebuild().catch(() => {
        // Keep serving the last good build when a rebuild fails.
      });
    }, REBUILD_DEBOUNCE_MS);
  }

  devServer(): DevServer {
    if (!this.server || !this.wss || !this.watcher) {
      throw new Error('DevServerPlugin has not been started');
    }
    return {
      server: this.server,
      port: this.port,
      host: this.host,
      watcher: this.watcher,
      wss: this.wss,
      rebuild: () => this.rebuild(),
      close: () => this.onEnd(),
      onRebuild: (callback: () => void) => {
        this.rebuildCallbacks.push(callback);
      },
    };
  }
}

export async function startDevServer(options: ServeOptions): Promise<DevServer> {
  const { plugins, config } = await loadConfiguredPlugins();
  const devPlugin = new DevServerPlugin(options);
  const engine = createEngine(options as BuildOptions, [...plugins, devPlugin], config);
  await engine.start();
  await engine.build();
  return devPlugin.devServer();
}

